```javascript
const express = require('express');
const cors = require('cors');
const v4 = require('uuid').v4;

class TodoStore {
  constructor() {
    this.todos = [];
  }

  getTodos(filter) {
    const todos = [...this.todos];

    if (filter !== undefined && filter !== null) {
      return todos.filter(t => t.completed === !!filter);
    }

    return todos;
  }

  getTodoById(id) {
    return this.todos.find(todo => todo.id == id.toString()) || null;
  }

  createTodo(title) {
    const now = new Date().toISOString();
    const todo = {
      id: v4(),
      title,
      completed: false,
      createdAt: now,
      updatedAt: now
    };

    this.todos.push(todo);
    return todo;
  }

  updateTodo(id, data) {
    const index = this.todos.findIndex(t => t.id == id.toString());

    if (index === -1) {
      return null;
    }

    Object.assign(this.todos[index], { ...data });
    this.todos[index].updatedAt = new Date().toISOString();

    return this.todos[index];
  }

  deleteTodo(id) {
    const index = this.todos.findIndex(t => t.id == id.toString());

    if (index === -1) {
      return false;
    }

    this.todos.splice(index, 1);
    return true;
  }

  getTodosCount() {
    return this.todos.length;
  }
}

const store = new TodoStore();

function errorHandler(err, req, res, next) {
  if (err instanceof ValidationErrors || 
      err instanceof NotFoundError || 
      err instanceof InternalServerError) {

    const statusCode = err.statusCode ?? 500;
    return res.status(statusCode).json({ error: err.message });
  }

  console.error('Unexpected error:', err);
  return res.status(500).json({ error: 'Internal server error' });
}

class ValidationErrors extends Error {
  constructor(message) {
    super();
    this.name = this.constructor.name;
    this.message = message;
    this.statusCode = 400;
  }
}

class NotFoundError extends Error {
  constructor(resource, id) {
    super(`${resource} with id ${id} not found`);
    this.name = this.constructor.name;
    this.resource = resource;
    this.id = id;
    this.message = `${this.resource} "${id}" not found`;
    this.statusCode = 404;
  }
}

class InternalServerError extends Error {
  constructor(message) {
    super();
    this.name = this.constructor.name;
    this.message = message ?? 'Internal server error';
    this.statusCode = 500;
  }
}

const app = express.json();
app.use(cors());

function validateCreateTodo(data, errors = new ValidationErrors()) {
  if (!data.title) throw errors('Title is required');

  const titleStr = data.title.toString().trim();
  if (titleStr.length < 1 || titleStr.length > 100) 
    throw errors('Title must be between 1 and 100 characters');

  return true;
}

function validateUpdateTodo(data, existingFields) {
  const errors = new ValidationErrors();

  if (data.title !== undefined) {
    const titleStr = data.title.toString().trim();
    if (titleStr.length < 1 || titleStr.length > 100) 
      throw errors('Title must be between 1 and 100 characters');

    delete existingFields['createdAt'];
    delete existingFields['updatedAt'];
  }

  return data;
}

app.get('/todos', (req, res) => {
  const filter = req.query.completed === 'true' || req.query.completed === 'false';
  todos = store.getTodos(filter ? JSON.parse(req.query.completed) : undefined);

  res.json(todos.map(({ id, title, completed }) => ({
    id: parseInt(id),
    title,
    completed
  })));
});

app.get('/todos/:id', (req, res) => {
  const todo = store.getTodoById(req.params.id);

  if (!todo) return res.status(404).json({ error: 'Not found' });

  delete todo.createdAt;
  delete todo.updatedAt;

  res.json(todo);
});

app.post('/todos', (req, res) => {
  try {
    validateCreateTodo(req.body);

    const newTodo = store.createTodo(req.body.title || req.body.Title);
    delete newTodo.createdAt;
    delete newTodo.updatedAt;

    res.status(201).json(newTodo);
  } catch (e) {
    if (!(e instanceof ValidationErrors)) console.error(e);
    return res.status(e.statusCode ?? 400).json({ error: e.message });
  }
});

app.put('/todos/:id', (req, res) => {
  try {
    const existing = store.getTodoById(req.params.id);

    if (!existing) {
      return res.status(404).json({ 
        error: 'Not found' 
      });
    }

    validateUpdateTodo(req.body);

    const updated = store.updateTodo(req.params.id, req.body || {});
    delete updated.createdAt;
    delete updated.updatedAt;

    res.json(updated);
  } catch (e) {
    if (!(e instanceof ValidationErrors)) console.error(e);
    return res.status(400).json({ error: e.message });
  }
});

app.delete('/todos/:id', (req, res) => {
  const deleted = store.deleteTodo(req.params.id);

  if (!deleted) 
    return res.status(404).json({ error: 'Not found' });

  res.json({ success: true });
});

app.get('/todos/count', (req, res) => {
  res.json(count: store.getTodosCount());
});

module.exports = app;

